#!/usr/bin/env bash
set -euo pipefail

# validate.sh - run the checkout service contract tests and emit a summary.
# Called by the checkout-validator skill; run from the repo root.

CARGO_FLAGS=&quot;--quiet&quot;
PKG=&quot;ship-platform&quot;
FILTER=&quot;checkout&quot;

echo &quot;=== checkout-validator: running tests ===&quot;
cargo test ${CARGO_FLAGS} -p ${PKG} ${FILTER}
STATUS=$?
echo &quot;=== done (exit ${STATUS}) ===&quot;
exit ${STATUS}
